-- CHANGE LOG
-- 1 | maintainer@emeraldcoastsystemsgroup.com | The native paper book (TRADE-01): the person's autopilot configuration, the simulated account (cash, equity, high-water mark, realized P&L), open positions with their trailing peak, every simulated fill, the decision behind each fill, one record per five-minute tick (the idempotency anchor), and one equity snapshot per New York session date. Declared here so the native kernel provisions them in a person's scope before the first read; every row carries user_sub and every query filters on it. Fills are simulated against the kernel's latest prices; nothing here describes a broker order.
CREATE TABLE IF NOT EXISTS trading_paper_config (user_sub TEXT NOT NULL PRIMARY KEY, armed BOOLEAN NOT NULL DEFAULT false, posture TEXT NOT NULL DEFAULT 'balanced', starting_cash DOUBLE PRECISION NOT NULL, max_shares INTEGER NOT NULL, max_notional DOUBLE PRECISION NOT NULL, max_orders_per_tick INTEGER NOT NULL, max_quote_age_minutes INTEGER NOT NULL, universe TEXT, armed_at TIMESTAMPTZ, disarmed_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trading_paper_account (user_sub TEXT NOT NULL PRIMARY KEY, cash DOUBLE PRECISION NOT NULL, equity DOUBLE PRECISION NOT NULL, high_water DOUBLE PRECISION NOT NULL, realized_pl DOUBLE PRECISION NOT NULL DEFAULT 0, starting_cash DOUBLE PRECISION NOT NULL, version INTEGER NOT NULL DEFAULT 0, last_tick_window TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trading_paper_positions (user_sub TEXT NOT NULL, symbol TEXT NOT NULL, qty INTEGER NOT NULL, avg_cost DOUBLE PRECISION NOT NULL, last_price DOUBLE PRECISION, last_price_at TIMESTAMPTZ, peak_price DOUBLE PRECISION, opened_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (user_sub, symbol));
CREATE TABLE IF NOT EXISTS trading_paper_orders (order_id TEXT NOT NULL PRIMARY KEY, user_sub TEXT NOT NULL, tick_window TEXT NOT NULL, decision_id TEXT NOT NULL, symbol TEXT NOT NULL, side TEXT NOT NULL, qty INTEGER NOT NULL, fill_price DOUBLE PRECISION NOT NULL, notional DOUBLE PRECISION NOT NULL, reason TEXT NOT NULL, realized_pl DOUBLE PRECISION, status TEXT NOT NULL DEFAULT 'filled', quote_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_trading_paper_orders_window ON trading_paper_orders (user_sub, tick_window, symbol, side);
CREATE TABLE IF NOT EXISTS trading_paper_decisions (decision_id TEXT NOT NULL PRIMARY KEY, user_sub TEXT NOT NULL, tick_window TEXT NOT NULL, symbol TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL, score DOUBLE PRECISION, confidence DOUBLE PRECISION, regime DOUBLE PRECISION, rationale TEXT NOT NULL, per_timeframe TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trading_paper_ticks (user_sub TEXT NOT NULL, tick_window TEXT NOT NULL, trigger_kind TEXT NOT NULL, run_id TEXT, outcome TEXT NOT NULL, order_count INTEGER NOT NULL DEFAULT 0, equity DOUBLE PRECISION, summary TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (user_sub, tick_window));
CREATE TABLE IF NOT EXISTS trading_paper_equity_daily (user_sub TEXT NOT NULL, session_date TEXT NOT NULL, equity DOUBLE PRECISION NOT NULL, cash DOUBLE PRECISION NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (user_sub, session_date));
